let el=document.getElementById("profile_card_id");const height=el.clientHeight,width=el.clientWidth;el.addEventListener("mousemove",handleMove);function handleMove(e){const t=e.layerX,n=e.layerY,s=30*((t-width/2)/width),o=-30*((n-height/2)/height),i="perspective(500px) scale(1.0) rotateX("+o+"deg) rotateY("+s+"deg)";el.style.transform=i}el.addEventListener("mouseout",function(){el.style.transform="perspective(500px) scale(1) rotateX(0) rotateY(0)"}),el.addEventListener("mouseup",function(){el.style.transform="perspective(500px) scale(1.0) rotateX(0) rotateY(0)"})